integrations.replacement:
// Demo session: a parent/guardian is dropped
// straight onto the partner side of the app so the reporting experience
// can be previewed without a real partner account — there is no backend
// to source the account role from. Students keep the normal home entry
// below.
if (DemoSession.demoActive && role == OnboardingRole.parent) {
  context.router.replaceNamed('/partner-dashboard');
  return;
}
// Production parent/guardian: land on the partner accept-invite page —
// the common case is a parent holding their student's 6-digit pairing
// code (P3.2 typed codes, no deep links); the page links onward to
// partner-first signup (/partner-signup) for parents without a code.
if (role == OnboardingRole.parent) {
  context.router.replaceNamed('/partner-accept-invite');
  return;
}
// TEMPORARY admin shortcut (onboarding_sdk's kShowAdminOnboardingChoice):
// straight to the profile, where the operator rows (lesson review,
// homework queue, announcements) each show only when the backend's own
// never-throwing gate says yes. Creates and touches no student/partner
// profile; an account with nothing to manage gets one friendly line
// instead of a bare screen.
if (role == OnboardingRole.admin) {
  final messenger = ScaffoldMessenger.maybeOf(context);
  Future.wait([
    supachargeLessonReviewAllowed(),
    supachargeAnnouncementsAllowed(),
  ]).then((allowed) {
    if (!allowed.contains(true)) {
      messenger?.showSnackBar(const SnackBar(
        content: Text('Nothing to manage on this account'),
      ));
    }
  });
  context.router.replaceNamed('/profile');
  return;
}

// Supacharge (home SDK contribution): registration asks for date of
// birth. Terms feature — an adult (18+ at acceptance time, measured
// from User.birth_date) self-qualifies for full-name display on the
// weekly league; a minor stays masked until a partner-granted terms
// acceptance (teacher/sponsor) is on record. Apps that don't set this
// keep auth_sdk's default registration form untouched.
AuthRegistrationConfig.collectsBirthDate = true;
